from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from typing import Any

from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _parse_upload_time(value: Any) -> datetime | None:
    """Parse a PyPI ``upload_time_iso_8601`` string into a ``datetime``.

    Returns ``None`` when the value is missing or not a valid ISO-8601 string.
    """
    if not isinstance(value, str) or not value:
        return None
    # ``datetime.fromisoformat`` on older Python versions does not understand the
    # trailing ``Z`` used by PyPI, so normalize it to an explicit UTC offset.
    if value.endswith("Z"):
        value = value[:-1] + "+00:00"
    try:
        return datetime.fromisoformat(value)
    except ValueError:
        return None


@dataclass(frozen=True)
class Release:
    """A single package release (one version) aggregated across its distributions."""

    version: Version
    upload_time: datetime
    yanked: bool
    requires_python: SpecifierSet | None

    @classmethod
    def from_distributions(
        cls, version: str, distributions: list[dict[str, Any]]
    ) -> Release | None:
        """Build a ``Release`` from a version string and its list of distributions.

        Returns ``None`` (i.e. the release must be dropped) when:

        * there are no distributions,
        * the version string is not a valid PEP 440 version, or
        * no distribution has a parseable ``upload_time_iso_8601`` field.
        """
        if not distributions:
            return None

        try:
            parsed_version = Version(version)
        except InvalidVersion:
            return None

        upload_times = [
            t
            for dist in distributions
            if (t := _parse_upload_time(dist.get("upload_time_iso_8601"))) is not None
        ]
        if not upload_times:
            return None

        # A release is considered yanked only when *every* distribution is yanked.
        yanked = all(bool(dist.get("yanked", False)) for dist in distributions)

        # Use the first non-empty, valid ``requires_python`` across distributions.
        requires_python: SpecifierSet | None = None
        for dist in distributions:
            raw = dist.get("requires_python")
            if not raw:
                continue
            try:
                requires_python = SpecifierSet(raw)
                break
            except InvalidSpecifier:
                continue

        return cls(
            version=parsed_version,
            upload_time=min(upload_times),
            yanked=yanked,
            requires_python=requires_python,
        )


@dataclass(frozen=True)
class Package:
    """Typed representation of a PyPI package and its releases."""

    name: str
    releases: tuple[Release, ...]

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> Package:
        """Parse a PyPI JSON API response into a ``Package``.

        Releases without distributions, without a parseable upload time, or with an
        unparseable version are dropped.
        """
        info = data.get("info") or {}
        name = info.get("name") or ""

        raw_releases = data.get("releases") or {}
        releases = [
            release
            for version, distributions in raw_releases.items()
            if (release := Release.from_distributions(version, distributions or []))
            is not None
        ]
        releases.sort(key=lambda r: r.version)
        return cls(name=name, releases=tuple(releases))

    @property
    def versions(self) -> tuple[Version, ...]:
        """All valid release versions, sorted in ascending order."""
        return tuple(r.version for r in self.releases)

    @property
    def latest_version(self) -> Version | None:
        """Highest stable (non-pre-release, non-dev, non-yanked) version, or ``None``."""
        stable = [
            r.version
            for r in self.releases
            if not r.yanked
            and not r.version.is_prerelease
            and not r.version.is_devrelease
        ]
        return max(stable) if stable else None

    def get_release(self, version: str | Version) -> Release | None:
        """Return the ``Release`` matching ``version``, or ``None`` if absent."""
        if isinstance(version, str):
            try:
                version = Version(version)
            except InvalidVersion:
                return None
        return next((r for r in self.releases if r.version == version), None)
