from __future__ import annotations

import asyncio
import json
import os
import time
import urllib.error
import urllib.request
from typing import Any, Iterable

from ._models import Package

DEFAULT_BASE_URL = "https://pypi.org"

# HTTP status codes that indicate a transient failure worth retrying.
_RETRYABLE_STATUS_CODES = frozenset({429, 500, 502, 503, 504})

# Maximum total number of attempts (initial request + retries).
_MAX_ATTEMPTS = 3

# Base delay (seconds) used for exponential backoff between retries.
_BACKOFF_BASE_SECONDS = 0.5


class PyPIError(RuntimeError):
    """Raised for all unrecoverable errors when fetching from PyPI."""


# In-memory cache mapping package name -> parsed ``Package``.
_cache: dict[str, Package] = {}


def _base_url() -> str:
    """Return the base URL, honoring the ``PYPI_URL`` environment variable."""
    override = os.environ.get("PYPI_URL")
    if override:
        return override.rstrip("/")
    return DEFAULT_BASE_URL


def _fetch_json(name: str) -> dict[str, Any]:
    """Fetch and parse the JSON metadata for ``name`` from the PyPI JSON API."""
    url = f"{_base_url()}/pypi/{name}/json"
    last_error: Exception | None = None

    for attempt in range(_MAX_ATTEMPTS):
        try:
            with urllib.request.urlopen(url) as response:
                body = response.read()
            data = json.loads(body)
            if not isinstance(data, dict):
                raise PyPIError(
                    f"Unexpected response for package {name!r}: "
                    f"expected a JSON object, got {type(data).__name__}"
                )
            return data
        except urllib.error.HTTPError as e:
            if e.code == 404:
                raise PyPIError(f"Package not found: {name}") from e
            if e.code not in _RETRYABLE_STATUS_CODES:
                raise PyPIError(
                    f"HTTP {e.code} error while fetching package {name!r}"
                ) from e
            last_error = e
        except (urllib.error.URLError, ConnectionResetError) as e:
            last_error = e

        # Sleep before the next attempt (but not after the final one).
        if attempt < _MAX_ATTEMPTS - 1:
            time.sleep(_BACKOFF_BASE_SECONDS * (2**attempt))

    raise PyPIError(
        f"Failed to fetch package {name!r} after {_MAX_ATTEMPTS} attempts"
    ) from last_error


def get_package(name: str) -> Package:
    """Fetch package metadata for ``name``, memoizing the result in memory."""
    if name in _cache:
        return _cache[name]
    package = Package.from_json(_fetch_json(name))
    _cache[name] = package
    return package


def clear_cache() -> None:
    """Clear the in-memory cache used by :func:`get_package`."""
    _cache.clear()


async def aget_package(name: str) -> Package:
    """Async wrapper around :func:`get_package`."""
    return await asyncio.to_thread(get_package, name)


async def aget_packages(names: Iterable[str]) -> list[Package]:
    """Fetch multiple packages concurrently, preserving input order."""
    names = list(names)
    return await asyncio.gather(*(aget_package(name) for name in names))
